import React, { useEffect, useState } from 'react';
import { motion } from 'framer-motion';
import {
  IconDashboard,
  IconTasks,
  IconProfile,
  IconPomodoro,
  IconBook,
} from '../assets/icons';
import { useLocation, useNavigate } from 'react-router-dom';

// Variants for dock animations - enhanced for better neural effect
const dockVariants = {
  hidden: { y: 100, opacity: 0 },
  visible: { 
    y: 0, 
    opacity: 1,
    transition: { 
      type: "spring", 
      stiffness: 250, 
      damping: 25,
      staggerChildren: 0.05
    }
  }
};

const iconVariants = {
  hidden: { y: 20, opacity: 0 },
  visible: { 
    y: 0, 
    opacity: 1,
    transition: { type: "spring", stiffness: 300, damping: 20 }
  }
};

// Advanced Neural network connection line between icons
const NeuralConnector = ({ startX, endX, isActive }) => {
  // Generate random points along the path for a more organic look
  const [pathPoints, setPathPoints] = useState([]);
  
  useEffect(() => {
    // Create a slightly curved path with some variance
    const numPoints = Math.floor(Math.random() * 2) + 2; // 2-3 points
    const newPoints = [];
    
    for (let i = 0; i <= numPoints; i++) {
      const x = startX + ((endX - startX) * i / numPoints);
      
      // Add some vertical variance
      const variance = i === 0 || i === numPoints ? 0 : (Math.random() - 0.5) * 8;
      newPoints.push({ x, variance });
    }
    
    setPathPoints(newPoints);
  }, [startX, endX]);
  
  // Create path string from points
  const pathData = pathPoints.length > 0 
    ? `M ${pathPoints[0].x} 50 ` + 
      pathPoints.slice(1).map(point => `L ${point.x} ${50 + point.variance}`).join(' ')
    : `M ${startX} 50 L ${endX} 50`;
  
  return (
    <svg 
      className="absolute top-1/2 h-8 pointer-events-none" 
      style={{ 
        left: 0,
        width: '100%',
        transform: 'translateY(-50%)',
        zIndex: 0
      }}
    >
      {/* Base connection line */}
      <path 
        d={pathData}
        stroke={isActive ? "rgba(100, 200, 255, 0.4)" : "rgba(100, 200, 255, 0.1)"} 
        strokeWidth={isActive ? "1.2" : "0.8"}
        strokeDasharray={isActive ? "none" : "3,3"}
        fill="none"
        style={{
          filter: isActive ? 'drop-shadow(0 0 3px rgba(100, 200, 255, 0.3))' : 'none'
        }}
      />
      
      {/* Multiple pulses for active connections */}
      {isActive && pathPoints.length > 0 && (
        <>
          <motion.circle 
            r="2.5"
            fill="#80CFFF"
            filter="url(#neural-glow)"
            initial={{ opacity: 0 }}
            animate={{ 
              opacity: [0, 0.8, 0],
              pathOffset: [0, 1]
            }}
            transition={{ 
              duration: 2, 
              repeat: Infinity,
              ease: "linear",
              repeatDelay: 2
            }}
            style={{
              offsetPath: `path("${pathData}")`,
              offsetRotate: "0deg"
            }}
          />
          
          <motion.circle 
            r="2"
            fill="#80CFFF"
            filter="url(#neural-glow)"
            initial={{ opacity: 0 }}
            animate={{ 
              opacity: [0, 0.6, 0],
              pathOffset: [0, 1]
            }}
            transition={{ 
              duration: 2.5, 
              repeat: Infinity,
              ease: "linear",
              delay: 1.5
            }}
            style={{
              offsetPath: `path("${pathData}")`,
              offsetRotate: "0deg"
            }}
          />
        </>
      )}
      
      {/* Endpoints */}
      {pathPoints.length > 0 && (
        <>
          <circle 
            cx={pathPoints[0].x} 
            cy={50 + (pathPoints[0].variance || 0)} 
            r="1.5" 
            fill={isActive ? "rgba(100, 200, 255, 0.7)" : "rgba(100, 200, 255, 0.3)"}
            style={{
              filter: isActive ? 'drop-shadow(0 0 1px rgba(100, 200, 255, 0.5))' : 'none'
            }}
          />
          
          <circle 
            cx={pathPoints[pathPoints.length - 1].x} 
            cy={50 + (pathPoints[pathPoints.length - 1].variance || 0)} 
            r="1.5" 
            fill={isActive ? "rgba(100, 200, 255, 0.7)" : "rgba(100, 200, 255, 0.3)"}
            style={{
              filter: isActive ? 'drop-shadow(0 0 1px rgba(100, 200, 255, 0.5))' : 'none'
            }}
          />
        </>
      )}
    </svg>
  );
};

// Memoized DockIcon for performance
const DockIcon = React.memo(({ icon: Icon, label, onClick, isActive, to }) => {
  // Enhanced click handler with event handling for Android
  const handleClick = React.useCallback((e) => {
    // Prevent event bubbling
    e.preventDefault();
    e.stopPropagation();
    
    // Add 300ms delay for Android devices to prevent double-click issues
    const isAndroid = /Android/i.test(navigator.userAgent);
    if (isAndroid) {
      // Android-specific optimization to avoid tap delay
      if (e.type === 'touchend') {
        e.preventDefault(); // Prevent mousedown after touchend
      }
    }
    
    // Call parent onClick with path
    onClick(to);
  }, [onClick, to]);

  return (
    <motion.div
      className="flex flex-col items-center justify-center cursor-pointer touch-manipulation relative"
      whileHover={{ 
        scale: 1.05,
        y: -3,
        transition: { 
          type: "spring", 
          stiffness: 400, 
          damping: 15
        } 
      }}
      whileTap={{ 
        scale: 0.95,
        transition: { duration: 0.1 } 
      }}
      onClick={handleClick}
      onTouchEnd={handleClick} // Added for better mobile touch support
      role="button"
      aria-label={`Navigate to ${label}`}
      aria-pressed={isActive}
      tabIndex={0}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          handleClick(e);
        }
      }}
      variants={iconVariants}
      data-testid={`dock-icon-${label.toLowerCase()}`}
      style={{
        WebkitTapHighlightColor: 'transparent', // Remove tap highlight on Android
        touchAction: 'manipulation', // Optimize for touch
      }}
    >
      {/* Hover indicator glow effect - enhanced */}
      {isActive && (
        <div 
          className="absolute -inset-1 rounded-xl opacity-70 -z-10 bg-gradient-to-b from-neural-400/20 to-neural-600/10 blur-sm"
          style={{
            filter: 'drop-shadow(0 0 8px rgba(100, 200, 255, 0.3))'
          }}
        />
      )}
      
      <div 
        className={`relative p-3 rounded-xl overflow-hidden flex items-center justify-center
          ${isActive 
            ? 'bg-gradient-to-b from-neural-400/50 to-neural-600/50 text-white shadow-lg border border-neural-300/20 backdrop-blur-lg' 
            : 'bg-gray-900/40 text-gray-300 hover:text-white backdrop-blur-md border border-gray-700/20 hover:border-neural-400/20'
          }`}
      >
        {/* Icon background effects */}
        <div className="absolute inset-0 overflow-hidden">
          {/* Glassmorphic grid */}
          <div 
            className="absolute inset-0 opacity-30"
            style={{
              backgroundImage: isActive 
                ? 'linear-gradient(rgba(100, 200, 255, 0.03) 1px, transparent 1px), linear-gradient(90deg, rgba(100, 200, 255, 0.03) 1px, transparent 1px)' 
                : 'linear-gradient(rgba(255, 255, 255, 0.02) 1px, transparent 1px), linear-gradient(90deg, rgba(255, 255, 255, 0.02) 1px, transparent 1px)',
              backgroundSize: '10px 10px'
            }}
          />
          
          {/* Top highlight */}
          <div 
            className="absolute top-0 left-0 right-0 h-px bg-gradient-to-r from-transparent via-white/20 to-transparent"
          />
          
          {/* Interior gradient */}
          {isActive && (
            <>
              <div className="absolute inset-0 bg-gradient-to-t from-neural-300/10 to-neural-400/5 opacity-50" />
              
              {/* Random neural nodes */}
              {Array.from({ length: 3 }).map((_, i) => (
                <motion.div
                  key={`icon-node-${i}`}
                  className="absolute rounded-full bg-neural-400/20"
                  style={{
                    width: `${2 + Math.random() * 2}px`,
                    height: `${2 + Math.random() * 2}px`,
                    left: `${10 + Math.random() * 80}%`,
                    top: `${10 + Math.random() * 80}%`,
                    filter: 'blur(1px)'
                  }}
                  animate={{
                    opacity: [0.2, 0.5, 0.2]
                  }}
                  transition={{
                    duration: 2 + Math.random() * 2,
                    repeat: Infinity,
                    delay: Math.random() * 2
                  }}
                />
              ))}
            </>
          )}
        </div>
        
        <Icon size={24} className="w-5 h-5 sm:w-6 sm:h-6 relative z-10" />
        
        {/* Pulsing highlight for active icon */}
        {isActive && (
          <motion.div
            className="absolute inset-0 bg-neural-400/5 rounded-xl z-0"
            animate={{ opacity: [0.3, 0.8, 0.3] }}
            transition={{ duration: 2, repeat: Infinity }}
          />
        )}
      </div>
      
      <span 
        className={`text-xs mt-1.5 ${
          isActive 
            ? 'neural-text-gradient text-pulse-neural font-medium' 
            : 'text-gray-300 font-light'
        }`}
      >
        {label}
      </span>
      
      {/* Active indicator with pulse effect */}
      {isActive && (
        <div className="absolute -bottom-1 left-1/2 -translate-x-1/2">
          <div className="w-1.5 h-1.5 bg-neural-300 rounded-full relative">
            <motion.div 
              className="absolute inset-0 bg-neural-300 rounded-full" 
              animate={{ scale: [1, 1.5, 1], opacity: [0.7, 0, 0.7] }}
              transition={{ duration: 2, repeat: Infinity }}
            />
          </div>
        </div>
      )}
    </motion.div>
  );
});

DockIcon.displayName = 'DockIcon';

// Add Leaderboard icon component
const IconLeaderboard = () => (
  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <path d="M16 6h2c1 0 2 .5 2 2v10c0 1.5-1 2-2 2H8c-1 0-2-.5-2-2V8c0-1.5 1-2 2-2h2"></path>
    <path d="M12 4c0 1.7-1.3 3-3 3h6c-1.7 0-3-1.3-3-3Z"></path>
    <path d="M9 14h6"></path>
    <path d="M9 17h3"></path>
    <path d="M13 17h2"></path>
    <path d="M19 9h-1"></path>
    <path d="M6 9h1"></path>
  </svg>
);

const DockBar = ({ activeTab, setActiveTab }) => {
  const location = useLocation();
  const navigate = useNavigate();
  
  // Improved path extraction to handle edge cases
  const currentPath = location.pathname === '/' 
    ? 'dashboard' 
    : location.pathname.substring(1) || 'dashboard';
  
  // Updated navigational mapping with leaderboard
  const navItems = [
    { icon: IconDashboard, label: "Dashboard", to: "/dashboard" },
    { icon: IconTasks, label: "Tasks", to: "/tasks" },
    { icon: IconPomodoro, label: "Pomodoro", to: "/pomodoro" },
    { icon: IconBook, label: "Books", to: "/books" },
    { icon: IconProfile, label: "Profile", to: "/profile" },
    { icon: IconLeaderboard, label: "Leaderboard", to: "/leaderboard" },
  ];
  
  // Update active tab based on current location
  React.useEffect(() => {
    setActiveTab(currentPath);
  }, [currentPath, setActiveTab]);
  
  // Client-side navigation handler without page refresh
  const handleIconClick = React.useCallback((path) => {
    try {
      // Normalize path
      const normalizedPath = path || '/dashboard';
      const tabId = normalizedPath.replace('/', '') || 'dashboard';
      
      // Update tab state
      setActiveTab(tabId);
      
      // Use React Router's navigation instead of window.location
      navigate(normalizedPath);
      
    } catch (error) {
      console.error("Navigation error:", error);
      // Fallback to dashboard on error
      navigate('/dashboard');
    }
  }, [setActiveTab, navigate]);

  return (
    <motion.nav 
      className="DockBar fixed bottom-0 left-0 right-0 bg-gray-900/90 backdrop-blur-xl border-t border-neural-900/30 shadow-lg py-1.5 sm:py-2 z-40"
      variants={dockVariants}
      initial="hidden"
      animate="visible"
      role="navigation"
      aria-label="Main navigation"
      style={{
        paddingBottom: 'env(safe-area-inset-bottom, 0px)', // Support for Android notches
        WebkitOverflowScrolling: 'touch', // Smooth scrolling on mobile
      }}
    >
      {/* Advanced background effects */}
      <div className="absolute inset-0 overflow-hidden">
        {/* Base background */}
        <div className="absolute inset-0 bg-gradient-to-t from-gray-950/90 to-gray-900/80 backdrop-blur-xl" />
        
        {/* Scanning line animation */}
        <motion.div 
          className="absolute h-px w-full bg-neural-400/10"
          style={{ top: '0px', boxShadow: '0 0 5px rgba(100, 200, 255, 0.2)' }}
          animate={{ 
            opacity: [0, 0.3, 0], 
            top: ['0%', '100%', '0%'] 
          }}
          transition={{ 
            duration: 8, 
            repeat: Infinity, 
            ease: "linear",
            repeatDelay: 4
          }}
        />
        
        {/* Grid background */}
        <div 
          className="absolute inset-0 opacity-10"
          style={{ 
            backgroundImage: 'linear-gradient(rgba(100, 200, 255, 0.1) 1px, transparent 1px), linear-gradient(90deg, rgba(100, 200, 255, 0.1) 1px, transparent 1px)',
            backgroundSize: '20px 20px'
          }}
        />
        
        {/* Top border */}
        <div className="absolute top-0 left-0 right-0 h-px bg-gradient-to-r from-neural-900/10 via-neural-400/20 to-neural-900/10" />
        
        {/* Random neural nodes */}
        {Array.from({ length: 4 }).map((_, i) => (
          <motion.div
            key={`bg-node-${i}`}
            className="absolute rounded-full bg-neural-400/15"
            style={{
              width: `${Math.random() * 4 + 2}px`,
              height: `${Math.random() * 4 + 2}px`,
              left: `${Math.random() * 100}%`,
              top: `${Math.random() * 100}%`,
              filter: 'blur(1px)'
            }}
            animate={{
              opacity: [0.2, 0.5, 0.2]
            }}
            transition={{
              duration: 3 + Math.random() * 2,
              repeat: Infinity,
              delay: Math.random() * 3
            }}
          />
        ))}
      </div>
      
      {/* SVG filters for glow effects */}
      <svg style={{ height: 0, width: 0, position: 'absolute' }}>
        <defs>
          <filter id="neural-glow" x="-50%" y="-50%" width="200%" height="200%">
            <feGaussianBlur stdDeviation="2" result="blur" />
            <feComposite in="SourceGraphic" in2="blur" operator="over" />
          </filter>
        </defs>
      </svg>
      
      <div className="max-w-screen-xl mx-auto px-2 sm:px-2 py-0.5 relative">
        {/* Neural connection lines */}
        <div className="absolute inset-y-0 left-0 right-0 overflow-hidden pointer-events-none">
          {navItems.slice(0, -1).map((item, index) => (
            <NeuralConnector 
              key={`connector-${index}`}
              startX={(index + 0.5) * (100 / navItems.length)}
              endX={(index + 1.5) * (100 / navItems.length)}
              isActive={activeTab === item.label.toLowerCase()}
            />
          ))}
        </div>
        
        <div className="flex items-center justify-around">
          {navItems.map((item) => (
            <DockIcon
              key={item.label}
              icon={item.icon}
              label={item.label}
              isActive={activeTab === item.label.toLowerCase()}
              onClick={handleIconClick}
              to={item.to}
            />
          ))}
        </div>
      </div>
      
      {/* Safe area inset for Android and iOS devices */}
      <div className="h-safe-area-inset-bottom bg-gray-900/80 backdrop-blur-xl" style={{ minHeight: '0px' }}></div>
    </motion.nav>
  );
};

export default DockBar; 